/** Public rendering seam: diagnostics and pinned docs evidence consume the same operator projection. */
export function renderManagedHostRunDoctorSection(
  managedHostRuns: ManagedHostRunRuntimeScan,
  managedHostRunGc: ManagedHostRunGcResult | null = null,
  brief = false,
): string[] {
  const lines = ['Managed host runs:'];
  lines.push(
    `  active=${managedHostRuns.active} terminal=${managedHostRuns.terminal} corrupt=${managedHostRuns.corrupt} `
    + `gcEligible=${managedHostRuns.eligibleForGc} retentionMs=${managedHostRuns.retentionMs}`,
  );
  if (!brief) {
    for (const run of managedHostRuns.runs) {
      lines.push(
        `  - ${run.runId} state=${run.state} worker=${run.workerLiveness} `
        + `heartbeatAt=${run.workerHeartbeatAt ?? 'none'} providerProgress=${run.providerProgressMode}:${run.lastProviderProgressAt ?? 'none'} `
        + `deadlineAt=${run.deadlineAt ?? 'unknown'} cancelAt=${run.cancelRequestedAt ?? 'none'} `
        + `residual=${run.residualProcessGroup ?? 'unknown'} replacementSafe=${run.replacementSafe ?? 'unknown'} `
        + `terminalReason=${run.terminalReason ?? 'none'} retentionExpired=${run.retentionExpired} oneShotInputs=${run.hasUnconsumedOneShotInputs}`,
      );
      if (run.error) lines.push(`    error: ${run.error}`);
    }
  }
  if (managedHostRunGc) {
    for (const runId of managedHostRunGc.removed) lines.push(`  ✓ removed expired terminal run ${runId}`);
    for (const runId of managedHostRunGc.archivedReceipts) lines.push(`  ✓ preserved sealed receipt archive ${runId}`);
    for (const failed of managedHostRunGc.failed) lines.push(`  ✗ failed to remove ${failed.runId}: ${failed.error}`);
  } else if (managedHostRuns.eligibleForGc > 0) {
    lines.push('  → Run lattice doctor --repair to remove only terminal runs beyond retention; active/corrupt/one-shot-input runs stay protected.');
  }
  lines.push('');
  return lines;
}

export function createDoctorHandlers(ctx: HandlerContext) {
  const { root, store } = ctx;

  return {
    // B-623a x B-7c05 merge: async (host burn scan awaits the store sweeps) AND
    // the brief/full render-only flags from main.
    async doctor(args?: { format?: 'text' | 'json'; limit?: number; repair?: boolean; full?: boolean; brief?: boolean }): Promise<string | object> {
      const limit = args?.limit ?? 1000;
      // B-7c05 CHK-004: RENDER-ONLY brief text mode, active ONLY on explicit
      // brief:true (injected by the CLI seam for bare invocations after
      // resolving flag > env > brief default). In-process callers and
      // --format=json keep today's full shape. Brief trims exactly the two
      // heavy sections (Recent issues detail, Validation scan detail) to
      // one-liners/counts; every failing/warning section stays visible.
      const brief = args?.brief === true && args?.format !== 'json';
      const issues = readHealthIssues(limit);
      const summary = summarizeHealthIssues(issues);
      const codex = runCodexAdapterChecks(root, {
          lines.push('  warnings: none');
        }
      } else {
        lines.push(renderValidationScan(validation));
      }
      lines.push('');
      lines.push('Codex adapter scan:');
      lines.push(renderCodexAdapterChecks(codex).split('\n').map((line, index) => index === 0 ? `  ${line}` : `  ${line}`).join('\n'));
      if (brief) {
        lines.push('');
        lines.push('→ Brief view. Full diagnostics: lattice doctor --full (or LATTICE_BRIEF_OUTPUT=0); --format=json keeps the full machine shape.');
      }

      return lines.join('\n');
    },
  };
}

/**
 * B-c054 (W2a): resolve the optional redEvidence policy block into exactly one
 * non-gating advisory health line for `lattice doctor`. The resolver reports the
 * §1.2 policyDigest when a valid block is present, else the fail-closed
 * diagnostic (e.g. `red_evidence_policy_missing: pinnedPath` when absent).
 * Doctor is not a gate: this scan catches its own errors, never throws, writes
 * no gate evidence, and never changes doctor's exit code.
 */
function scanRedEvidencePolicy(root: string): { line: string } {
  try {
    const config = loadConfig(root);
    return { line: resolveRedEvidenceDoctorLine(config.redEvidence) };
  } catch {
    const cause = error instanceof Error ? error.message : String(error);
    throw new Error(`managed host run ${runId}: existing archived receipt is corrupt (${cause})`);
  }
  if (existing.receipt?.receiptId !== archive.receipt.receiptId) {
    throw new Error(`managed host run ${runId}: existing archived receipt does not match terminal receipt`);
  }
  if (isCompleteValidReceiptArchive(existing, expected)) return;
  // ReceiptId-only leftovers (crash or pre-F-127) must not keep an incomplete
  // archive and then delete the only complete live artifacts.
  atomicWrite(archivePath, archive);
}

/**
 * Explicit bounded GC used by doctor --repair. Active/corrupt runs and any
 * directory still carrying one-shot secrets are retained fail-closed.
 */
export function pruneExpiredManagedHostRuns(
  root: string,
  options: { now?: number; retentionMs?: number } = {},
): ManagedHostRunGcResult {
  const scan = scanManagedHostRunRuntime(root, options);
  const result: ManagedHostRunGcResult = { removed: [], archivedReceipts: [], retained: [], failed: [] };
  for (const run of scan.runs) {
    if (run.state === 'corrupt') {
      result.retained.push({ runId: run.runId, reason: 'corrupt_runtime_retained_for_manual_review' });
      continue;
    }
    if (!['completed', 'failed', 'cancelled', 'timed_out'].includes(run.state)) {
      result.retained.push({ runId: run.runId, reason: 'active_run_protected' });
      continue;
    }
    if (run.hasUnconsumedOneShotInputs) {
      result.retained.push({ runId: run.runId, reason: 'one_shot_inputs_present_retained' });
      continue;
    }
    if (!run.retentionExpired) {
      result.retained.push({ runId: run.runId, reason: 'within_terminal_retention_window' });
      continue;
    }
    try {
      const paths = pathsFor(root, run.runId);
      const spec = readJson<ManagedHostRunSpec>(paths.spec);
      const archivePath = managedHostRunReceiptArchivePath(root, run.runId);
      mkdirSync(managedHostRunReceiptsRoot(root), { recursive: true, mode: 0o700 });
      const archive: ManagedHostRunReceiptArchive = {
        schemaVersion: 'lattice.managed_host_run_receipt_archive.v1',
        runId: run.runId,
        archivedAt: run.terminalAt ?? new Date(options.now ?? Date.now()).toISOString(),
        receipt: managedHostRunReceipt(root, run.runId),
        evidenceBindingDigest: digestFile(paths.evidenceBinding),
        // B-137a:F-127 — capture the binding BEFORE removeManagedHostRunRuntime
        // deletes spec.json/owner.json, otherwise verifyManagedReviewEvidence
        // can never reconstruct it and every imported receipt for this run turns
        // into managed_receipt_invalid (absent from SUPERSEDED_PASS_ISSUE_CODES,
        // so it hard-blocks REVIEW->TEST -- the F-100 deadlock mechanism).
        binding: readManagedHostRunBinding(root, run.runId),
        // B-137a:F-127 — capture the RAW BYTES before removeManagedHostRunRuntime
        // deletes them. The sealed evidenceProposalDigest is sha256 over the file
        // text, so storing a re-serialized object would not re-digest identically.
        evidenceProposalText: existsSync(paths.evidenceProposal)
          ? readFileSync(paths.evidenceProposal, 'utf8')
          : null,
        evidenceBindingText: existsSync(paths.evidenceBinding)
          ? readFileSync(paths.evidenceBinding, 'utf8')
          : null,
        evidenceBindingSealText: existsSync(paths.evidenceBindingSeal)
          ? readFileSync(paths.evidenceBindingSeal, 'utf8')
          : null,
      };
      persistManagedHostRunReceiptArchive(archivePath, archive, run.runId);
      if (spec.profile === 'cross_host_review_codex') {
        cleanupManagedCrossHostReviewWorktree(spec.root, spec.cwd);
      }
      removeManagedHostRunRuntime(root, run.runId);
      result.removed.push(run.runId);
      result.archivedReceipts.push(run.runId);
    } catch (error) {
      result.failed.push({ runId: run.runId, error: error instanceof Error ? error.message : String(error) });
    }
  }
  return result;
}

